+++ b/training/level-2/L2-006-inventory-store/inventoryStore.mjs
@@ -0,0 +1,116 @@
+import { promises as fs } from 'fs';
+import { dirname } from 'path';
+import { randomUUID } from 'crypto';
+
+const DB_FILE = 'inventory.json';
+const DB_PATH = dirname(import.meta.url);
+
+async function loadDB() {
+  try {
+    const data = await fs.readFile(DB_PATH + '/' + DB_FILE, 'utf-8');
+    return JSON.parse(data);
+  } catch (err) {
+    if (err.code === 'ENOENT') {
+      return [];
+    }
+    throw err;
+  }
+}
+
+async function saveDB(data) {
+  const tempFile = DB_PATH + '/inventory.tmp.' + randomUUID();
+  await fs.writeFile(tempFile, JSON.stringify(data, null, 2));
+  await fs.rename(tempFile, DB_PATH + '/' + DB_FILE);
+}
+
+export async function list() {
+  const data = await loadDB();
+  return data;
+}
+
+export async function get(id) {
+  const data = await loadDB();
+  const item = data.find(i => i.id === id);
+  return item || undefined;
+}
+
+export async function add(item) {
+  if (!item || !item.id || !item.name || !item.quantity || !item.unit || !item.price) {
+    throw new Error('INVALID_PATCH');
+  }
+  const data = await loadDB();
+  const existing = data.find(i => i.id === item.id);
+  if (existing) {
+    throw new Error('STATE_CORRUPT');
+  }
+  data.push(item);
+  await saveDB(data);
+  return JSON.parse(JSON.stringify(item));
+}
+
+export async function update(id, patch) {
+  if (!id || !patch || typeof patch !== 'object') {
+    throw new Error('INVALID_PATCH');
+  }
+  const data = await loadDB();
+  const item = data.find(i => i.id === id);
+  if (!item) {
+    throw new Error('STATE_CORRUPT');
+  }
+  const keys = Object.keys(patch);
+  const validKeys = ['name', 'quantity', 'unit', 'price'];
+  const invalidKeys = keys.filter(k => !validKeys.includes(k));
+  if (invalidKeys.length > 0) {
+    throw new Error('INVALID_PATCH');
+  }
+  const quantity = patch.quantity;
+  if (quantity !== undefined && typeof quantity !== 'number') {
+    throw new Error('INVALID_PATCH');
+  }
+  const price = patch.price;
+  if (price !== undefined && typeof price !== 'number') {
+    throw new Error('INVALID_PATCH');
+  }
+  const unit = patch.unit;
+  if (unit !== undefined && typeof unit !== 'string') {
+    throw new Error('INVALID_PATCH');
+  }
+  const name = patch.name;
+  if (name !== undefined && typeof name !== 'string') {
+    throw new Error('INVALID_PATCH');
+  }
+  Object.assign(item, patch);
+  await saveDB(data);
+  return JSON.parse(JSON.stringify(item));
+}
+
+export async function remove(id) {
+  const data = await loadDB();
+  const item = data.find(i => i.id === id);
+  if (!item) {
+    throw new Error('STATE_CORRUPT');
+  }
+  const index = data.indexOf(item);
+  data.splice(index, 1);
+  await saveDB(data);
+  return JSON.parse(JSON.stringify(item));
+}
+
+export async function adjust(id, delta) {
+  if (typeof delta !== 'number' || delta === 0) {
+    throw new Error('RANGE');
+  }
+  const data = await loadDB();
+  const item = data.find(i => i.id === id);
+  if (!item) {
+    throw new Error('STATE_CORRUPT');
+  }
+  const quantity = item.quantity;
+  const newQuantity = quantity + delta;
+  if (newQuantity <= 0) {
+    throw new Error('RANGE');
+  }
+  item.quantity = newQuantity;
+  await saveDB(data);
+  return JSON.parse(JSON.stringify(item));
+}

